function formatBytesVal(bytes) {
	const num = Number(bytes) || 0;
	if (num <= 0) return "0 B";
	const units = [
		"B",
		"KB",
		"MB",
		"GB",
		"TB"
	];
	const i = Math.min(units.length - 1, Math.floor(Math.log(num) / Math.log(1024)));
	return `${(num / Math.pow(1024, i)).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}
