	function exportWafAccessLogs() {
		const rows = wafAccessLogs.items || [];
		const header = [
			"verdict",
			"time",
			"domain",
			"method",
			"path",
			"ip",
			"country",
			"country_code",
			"reason",
			"status",
			"duration_ms",
			"user_agent"
		];
		const csv = [header.join(","), ...rows.map((item) => header.map((key) => csvCell(key === "time" ? item.timestamp : item[key])).join(","))].join("\n");
		const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
		const url = URL.createObjectURL(blob);
		const link = document.createElement("a");
		const site = websites.find((item) => String(item.id) === String(wafAccessLogFilters.websiteId));
		link.href = url;
		link.download = `spanel-access-logs-${site?.domain || "all"}.csv`;
		document.body.appendChild(link);
		link.click();
		link.remove();
		URL.revokeObjectURL(url);
	}
